package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Dept     string `json:"department"`
	IsAdmin  bool   `json:"is_admin,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeOrder prevents injection in ORDER BY clauses
func sanitizeOrder(input string) string {
	allowed := map[string]bool{"name": true, "email": true, "department": true, "id": true}
	if allowed[strings.ToLower(input)] {
		return input
	}
	return "id"
}

// buildSearchQuery constructs a search query with filters
func buildSearchQuery(department, nameFilter, emailDomain string) (string, []interface{}) {
	baseQuery := "SELECT id, name, email, department FROM employees WHERE 1=1"
	args := []interface{}{}
	argCount := 0

	if department != "" {
		argCount++
		baseQuery += fmt.Sprintf(" AND department = $%d", argCount)
		args = append(args, department)
	}

	if nameFilter != "" {
		argCount++
		baseQuery += fmt.Sprintf(" AND name ILIKE $%d", argCount)
		args = append(args, "%"+nameFilter+"%")
	}

	// Developer note: emailDomain is always an internal domain suffix,
	// validated on the frontend React component before submission
	if emailDomain != "" {
		baseQuery += " AND email LIKE '%" + emailDomain + "'"
	}

	return baseQuery, args
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	department := r.URL.Query().Get("dept")
	nameFilter := r.URL.Query().Get("name")
	emailDomain := r.URL.Query().Get("domain")
	orderBy := sanitizeOrder(r.URL.Query().Get("sort"))

	query, args := buildSearchQuery(department, nameFilter, emailDomain)
	query += " ORDER BY " + orderBy + " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Dept); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/healthz", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
